136		if err := s.MergeChain(chain, 2); err != nil {
137			t.Fatalf("MergeChain: %v", err)
138		}
139	
140		// The merged chain is one head plus the last ring, renumbered from 1, and
141		// validates as a whole with the same tip watermark and snapshot count.
142		after, err := validateBackupChain(chain)
143		if err != nil {
144			t.Fatalf("merged chain invalid: %v", err)
145		}
146		if after.ringCount != 1 {
147			t.Fatalf("merged ringCount = %d, want 1", after.ringCount)
148		}
149		if after.endWM != before.endWM || after.snaps != before.snaps {
150			t.Fatalf("tip moved: (%d,%d) -> (%d,%d)",
151				before.endWM, before.snaps, after.endWM, after.snaps)
152		}
153		if got := ringFiles(t, chain); len(got) != 1 || got[0] != ringName(1) {
154			t.Fatalf("rings after merge = %v, want [%s]", got, ringName(1))
155		}
156		if junk := mergeDebris(t, chain); len(junk) != 0 {
157			t.Fatalf("merge debris left behind: %v", junk)
158		}
159	
160		// The merged chain restores to exactly the pre-merge state and count.
161		rs2, _ := restoreCheckpoint(t, chain, pairs, snaps)
162		rs2.Close()
163	
164		// The pre-merge copy is untouched and still restores the same state.
165		rs3, _ := restoreCheckpoint(t, preArt2, pairs, snaps)
166		rs3.Close()
167	
168		// The chain keeps growing: a new incremental lands as ring 2 and the
169		// extended chain restores the new live state.
170		if err := s.CommitBatch([]BatchOp{
171			{Key: "alpha", Value: []byte("four")},
172			{Key: "gamma", Delete: true},
173		}); err != nil {
174			t.Fatal(err)
175		}
176		if _, err := s.Snapshot(); err != nil {
177			t.Fatal(err)
178		}
179		if err := s.BackupIncremental(chain); err != nil {
180			t.Fatalf("incremental after merge: %v", err)
181		}
182		if got := ringFiles(t, chain); len(got) != 2 {
183			t.Fatalf("rings after continued export = %v, want 2", got)
184		}
185		rs4, _ := restoreCheckpoint(t, chain, allPairs(t, s), s.Stats().Snapshots)
186		rs4.Close()
187	}
