690				t.Fatal(err)
691			}
692			if _, err := s.Snapshot(); err != nil {
693				t.Fatal(err)
694			}
695			if err := s.BackupIncremental(chain); err != nil {
696				t.Fatalf("ring %d: %v", r, err)
697			}
698		}
699		pairs, snaps := allPairs(t, s), s.Stats().Snapshots
700	
701		// One shot: fold the whole chain into a lone head.
702		oneShot := copyChain(t, chain)
703		if err := s.MergeChain(oneShot, rings); err != nil {
704			t.Fatalf("one-shot merge: %v", err)
705		}
706		if got := ringFiles(t, oneShot); len(got) != 0 {
707			t.Fatalf("one-shot rings = %v, want none", got)
708		}
709		rs, _ := restoreCheckpoint(t, oneShot, pairs, snaps)
710		rs.Close()
711	
712		// Piecemeal: merge the oldest ring into the head, thirty times over.
713		piecemeal := copyChain(t, chain)
714		for r := 0; r < rings; r++ {
715			if err := s.MergeChain(piecemeal, 1); err != nil {
716				t.Fatalf("piecemeal merge %d: %v", r, err)
717			}
718		}
719		if got := ringFiles(t, piecemeal); len(got) != 0 {
720			t.Fatalf("piecemeal rings = %v, want none", got)
721		}
722		rs2, _ := restoreCheckpoint(t, piecemeal, pairs, snaps)
723		rs2.Close()
724	
725		// Halving the chain keeps the back half of the rings, renumbered.
726		halved := copyChain(t, chain)
727		if err := s.MergeChain(halved, rings/2); err != nil {
728			t.Fatalf("halving merge: %v", err)
729		}
730		if got := ringFiles(t, halved); len(got) != rings/2 {
731			t.Fatalf("halved rings = %d, want %d", len(got), rings/2)
732		}
733		rs3, _ := restoreCheckpoint(t, halved, pairs, snaps)
734		rs3.Close()
735	}
736	
737	func TestMergeChainConcurrentActivity(t *testing.T) {
738		s := openStore(t, tempDir(t))
739		chain := filepath.Join(t.TempDir(), "chain")
740		if err := s.CommitBatch([]BatchOp{{Key: "seed", Value: []byte("0")}}); err != nil {
741			t.Fatal(err)
742		}
743		if err := s.Backup(chain); err != nil {
744			t.Fatal(err)
745		}
746	
747		stop := make(chan struct{})
748		var wg sync.WaitGroup
749		// Foreground writers, snapshotters, checkpoints and compactions run
750		// while exports and merges reshape the chain.
751		for w := 0; w < 2; w++ {
752			wg.Add(1)
753			go func(w int) {
754				defer wg.Done()
755				for i := 0; ; i++ {
756					select {
757					case <-stop:
758						return
759					default:
760					}
761					_ = s.CommitBatch([]BatchOp{
762						{Key: fmt.Sprintf("w%d-%04d", w, i%64), Value: []byte(fmt.Sprintf("%d", i))},
763					})
764				}
765			}(w)
766		}
767		wg.Add(1)
768		go func() {
769			defer wg.Done()
770			for {
771				select {
772				case <-stop:
773					return
774				default:
775				}
776				if snap, err := s.Snapshot(); err == nil {
777					snap.Close()
778				}
779				_ = s.Checkpoint()
780				_ = s.Compact()
781			}
782		}()
783	
784		// Exports and merges on this store are serialized with each other but
785		// never block the foreground above.
786		for i := 0; i < 20; i++ {
787			if err := s.BackupIncremental(chain); err != nil {
788				t.Fatalf("incremental %d: %v", i, err)
789			}
790			if err := s.MergeChain(chain, 1); err != nil {
791				t.Fatalf("merge %d: %v", i, err)
792			}
793		}
794		close(stop)
795		wg.Wait()
796	
797		// One last export brings the chain to the live state; it must restore
798		// exactly, with the cumulative snapshot count intact.
799		if err := s.BackupIncremental(chain); err != nil {
800			t.Fatal(err)
801		}
802		rs, _ := restoreCheckpoint(t, chain, allPairs(t, s), s.Stats().Snapshots)
803		rs.Close()
804		if junk := mergeDebris(t, chain); len(junk) != 0 {
805			t.Fatalf("debris left: %v", junk)
806		}
807	}
