347			defer wg.Done()
348			for i := 0; ; i++ {
349				select {
350				case <-stop:
351					return
352				default:
353				}
354				_ = s.CommitBatch([]BatchOp{
355					{Key: "a", Value: []byte(fmt.Sprintf("%d", i))},
356					{Key: fmt.Sprintf("w%05d", i), Value: []byte("x")},
357				})
358			}
359		}()
360		var rings []string
361		deadline := time.Now().Add(2 * time.Second)
362		for time.Now().Before(deadline) {
363			if err := s.BackupIncremental(chain); err != nil {
364				t.Fatalf("concurrent incremental: %v", err)
365			}
366			rings = append(rings, copyChain(t, chain))
367		}
368		close(stop)
369		wg.Wait()
370	
371		first, err := Restore(rings[0], filepath.Join(t.TempDir(), "a"))
372		if err != nil {
373			t.Fatal(err)
374		}
375		p1 := allPairs(t, first)
376		first.Close()
377		first2, err := Restore(rings[0], filepath.Join(t.TempDir(), "b"))
