274	func TestBackupConcurrentWithCommits(t *testing.T) {
275		s := openStore(t, tempDir(t))
276		for i := 0; i < 50; i++ {
277			if err := s.Put(fmt.Sprintf("init-%03d", i), []byte("i")); err != nil {
278				t.Fatal(err)
279			}
280		}
281	
282		var wg sync.WaitGroup
283		stop := make(chan struct{})
284		for g := 0; g < 4; g++ {
285			wg.Add(1)
286			go func(g int) {
287				defer wg.Done()
288				for i := 0; ; i++ {
289					select {
290					case <-stop:
291						return
292					default:
293					}
294					if err := s.CommitBatch([]BatchOp{
295						{Key: fmt.Sprintf("w%d-%05d", g, i), Value: []byte(fmt.Sprintf("%d", i))},
296						{Key: "shared", Value: []byte(fmt.Sprintf("%d-%d", g, i))},
297					}); err != nil {
298						return
299					}
300				}
301			}(g)
302		}
303	
304		// Wait until the writers' first commit is visible before exporting, so no
305		// backup anchors at a watermark that legitimately predates "shared".
306		deadline0 := time.Now().Add(3 * time.Second)
307		for {
308			if _, ok, _ := s.Get("shared"); ok {
309				break
310			}
311			if time.Now().After(deadline0) {
312				close(stop)
313				wg.Wait()
314				t.Fatal("writers never committed")
315			}
316			runtime.Gosched()
317		}
318	
319		// Several backups run while writes flow; each must succeed and restore to
320		// a self-consistent state, and the reads never block on the export.
321		var backups []string
322		deadline := time.Now().Add(3 * time.Second)
323		for time.Now().Before(deadline) {
324			bd := filepath.Join(t.TempDir(), "backup")
325			if err := s.Backup(bd); err != nil {
326				close(stop)
327				wg.Wait()
328				t.Fatalf("concurrent Backup: %v", err)
329			}
330			backups = append(backups, bd)
331		}
332		close(stop)
333		wg.Wait()
334	
335		for _, bd := range backups {
336			rs, err := Restore(bd, filepath.Join(t.TempDir(), "r"))
337			if err != nil {
338				t.Fatalf("restore concurrent backup: %v", err)
339			}
340			pairs := allPairs(t, rs)
341			// Restored state must be internally consistent: unique sorted keys and
342			// every value decodes as a non-negative decimal "g-i" marker for the
343			// shared key and init keys present.
344			for i := 1; i < len(pairs); i++ {
345				if pairs[i].Key <= pairs[i-1].Key {
346					t.Fatalf("restored pairs not strictly ordered at %d", i)
347				}
348			}
349			if _, ok, _ := rs.Get("shared"); !ok {
350				t.Fatal("shared key missing in restored backup")
351			}
352			if _, ok, _ := rs.Get("init-000"); !ok {
353				t.Fatal("pre-backup key missing in restored backup")
354			}
355			rs.Close()
356		}
357	}
