406	// corruptArtifact builds a good backup then applies a mutation before each
407	// restore attempt, which must be rejected wholesale.
408	func TestRestoreRejectsCorruption(t *testing.T) {
409		s := openStore(t, tempDir(t))
410		// Enough keys for multiple segments.
411		ops := make([]BatchOp, backupEntriesPerSegment+50)
412		for i := range ops {
413			ops[i] = BatchOp{Key: fmt.Sprintf("k-%06d", i), Value: []byte(fmt.Sprintf("val%d", i))}
414		}
415		if err := s.CommitBatch(ops); err != nil {
416			t.Fatal(err)
417		}
418		good := filepath.Join(t.TempDir(), "good")
419		if err := s.Backup(good); err != nil {
420			t.Fatal(err)
421		}
422	
423		copyDir := func(t *testing.T) string {
424			t.Helper()
425			dst := filepath.Join(t.TempDir(), "artifact")
426			if err := os.MkdirAll(dst, 0o700); err != nil {
427				t.Fatal(err)
428			}
429			entries, err := os.ReadDir(good)
430			if err != nil {
431				t.Fatal(err)
432			}
433			for _, e := range entries {
434				data, err := os.ReadFile(filepath.Join(good, e.Name()))
435				if err != nil {
436					t.Fatal(err)
437				}
438				if err := os.WriteFile(filepath.Join(dst, e.Name()), data, 0o600); err != nil {
439					t.Fatal(err)
440				}
441			}
442			return dst
443		}
444	
445		expectReject := func(t *testing.T, artifact string) {
