750	// TestQueuedBatchMemoryDoesNotScaleWithLiveKeys guards the group-commit
751	// tightening: a long queue coalescing behind one sync against a thousand-key
752	// store must publish correct state and leave the committed view shallow; the
753	// temporary maps it builds never scale with the queue length.
754	func TestQueuedBatchMemoryDoesNotScaleWithLiveKeys(t *testing.T) {
755		s := openStore(t, tempDir(t))
756		const liveKeys = 1500
757		seed := make([]BatchOp, liveKeys)
758		for i := range seed {
759			seed[i] = BatchOp{Key: fmt.Sprintf("live-%05d", i), Value: []byte("payload")}
760		}
761		if err := s.CommitBatch(seed); err != nil {
762			t.Fatal(err)
763		}
764	
765		probe := func() {
766			const followers = 200
767			proceed := make(chan struct{})
768			var leaderWG sync.WaitGroup
769			leaderWG.Add(1)
770			s.leaderHook = func() {
771				leaderWG.Done()
772				<-proceed
773			}
774			leaderErr := make(chan error, 1)
775			go func() {
776				leaderErr <- s.CommitBatch([]BatchOp{{Key: "leader", Value: []byte("L")}})
777			}()
778			leaderWG.Wait()
779	
780			var wg sync.WaitGroup
781			for i := 0; i < followers; i++ {
782				wg.Add(1)
783				go func(i int) {
784					defer wg.Done()
785					if err := s.CommitBatch([]BatchOp{{Key: fmt.Sprintf("q-%04d", i), Value: []byte("x")}}); err != nil {
786						t.Errorf("follower %d: %v", i, err)
787					}
788				}(i)
789			}
790			for queueLen(s) != followers+1 {
791				runtime.Gosched()
792			}
793			close(proceed)
794			if err := <-leaderErr; err != nil {
795				t.Errorf("leader: %v", err)
796			}
797			wg.Wait()
798			s.leaderHook = nil
799		}
800	
801		// Repeated queueing must not accumulate overlay depth or stale maps.
802		for round := 0; round < 4; round++ {
803			probe()
804			if d := s.current.Load().depth; d > viewFlattenLimit {
805				t.Fatalf("round %d: post-group view depth %d exceeds %d", round, d, viewFlattenLimit)
806			}
807			runtime.GC()
808		}
809	
810		if got, ok, _ := s.Get("live-00000"); !ok || string(got) != "payload" {
811			t.Fatalf("live state wrong after queued groups: %q %v", got, ok)
812		}
813		if got, ok, _ := s.Get("q-0199"); !ok || string(got) != "x" {
814			t.Fatalf("queued write missing: %q %v", got, ok)
815		}
816		if st := s.Stats(); st.Keys != liveKeys+200+1 {
817			t.Fatalf("keys after queued groups: %d, want %d", st.Keys, liveKeys+201)
818		}
819	
820		// The retained state must reopen intact.
821		dir := s.dir
822		if err := s.Close(); err != nil {
823			t.Fatal(err)
824		}
825		s2, err := Open(dir)
826		if err != nil {
827			t.Fatal(err)
828		}
829		defer s2.Close()
830		if st := s2.Stats(); st.Keys != liveKeys+200+1 {
831			t.Fatalf("keys after reopen: %d, want %d", st.Keys, liveKeys+201)
832		}
833	}
