// Every rewrite is the same all-or-nothing install, so contenders only ever
// read a complete record; a failed renewal simply lets this lease age (the
// operation itself is unaffected).
func (t *leaseToken) renew(initial []byte) {
	defer close(t.done)
	gap := leaseRenewGap
	if gap <= 0 {
		gap = leaseTTL / 3
	}
	ticker := time.NewTicker(gap)
	defer ticker.Stop()
	for {
		select {
		case <-t.stop:
			return
		case <-ticker.C:
			t.rec.expires = leaseNow().Add(leaseTTL).UnixNano()
			if err := writeLeaseRecord(t.path, t.tmpPath, encodeLease(t.rec)); err != nil {
