// live merge sibling lease exists every staging/trash sibling belongs to that
// running merge and is left exactly where it is. Once the lease is dead
// (expired, corrupt or absent) the existing repair runs and the dead lease
// record is removed with the debris.
func sweepMergeDebrisLeased(chainDir string) {
	parent := filepath.Dir(chainDir)
	base := filepath.Base(chainDir)
	leasePath := mergeLeasePath(chainDir)

	entries, err := os.ReadDir(parent)
	if err != nil {
		return
	}
	var staging, trash []string
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		name := e.Name()
		if isMergeTempName(name, base, mergeStagePrefix) {
			staging = append(staging, name)
		}
		if isMergeTempName(name, base, mergeTrashPrefix) {
			trash = append(trash, name)
		}
	}

	// A live merge owns whatever staging/trash siblings exist: recover
	// nothing. The chain itself must not be moved or deleted under it.
	if rec, live, _, lerr := leaseStateAtPath(leasePath); lerr == nil && live {
		_ = rec
		return
	}

	if len(staging) == 0 && len(trash) == 0 {
		// No debris: still reap a dead sibling lease if one lingers.
		if _, derr := reclaimDeadLeaseAt(leasePath); derr == nil {
			// best effort
		}
		return
	}

	changed := false
	if _, err := os.Stat(chainDir); errors.Is(err, fs.ErrNotExist) && len(trash) > 0 {
		// Killed between the two commit renames: the whole old chain is parked
		// in the trash sibling. Move it back before clearing anything; the
		// chain name must never disappear with the old chain parked aside.
		if err := os.Rename(filepath.Join(parent, trash[0]), chainDir); err == nil {
			changed = true
			trash = trash[1:]
		}
	}
	for _, name := range staging {
		if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
			changed = true
		}
	}
	for _, name := range trash {
		if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
			changed = true
		}
	}
	if removed, err := reclaimDeadLeaseAt(leasePath); err == nil && removed {
		changed = true
	}
	if changed {
		_ = syncDirectory(parent)
	}
}

