		}
		data := encodeLease(rec)
		if err := writeLeaseRecord(claimPath, claimTmp, data); err != nil {
			if errors.Is(err, fs.ErrExist) {
				continue // another contender won the rename; re-inspect
			}
			return nil, err
		}
		tok := &leaseToken{
			path:    claimPath,
			tmpPath: claimTmp,
			rec:     rec,
			stop:    make(chan struct{}),
			done:    make(chan struct{}),
		}
		go tok.renew(data)
		return tok, nil
	}
	return nil, errLeaseBusy
}

// renew keeps the lease ahead of its expiry while the holder operation runs.
// Every rewrite is the same all-or-nothing install, so contenders only ever
// read a complete record; a failed renewal simply lets this lease age (the
// operation itself is unaffected).
func (t *leaseToken) renew(initial []byte) {
	defer close(t.done)
	gap := leaseRenewGap
	if gap <= 0 {
		gap = leaseTTL / 3
	}
	ticker := time.NewTicker(gap)
	defer ticker.Stop()
	for {
		select {
		case <-t.stop:
			return
		case <-ticker.C:
			t.rec.expires = leaseNow().Add(leaseTTL).UnixNano()
			if err := writeLeaseRecord(t.path, t.tmpPath, encodeLease(t.rec)); err != nil {
				return
			}
		}
	}
}

// release surrenders the lease. It removes only a record that still
// identifies this exact holder: if the lease aged out, was reclaimed and was
// taken over by another holder, that newer lease is left in place. Removing
// the record never touches the chain itself.
func (t *leaseToken) release() {
	close(t.stop)
	<-t.done
	if rec, live, _, err := leaseStateAtPath(t.path); err == nil && live && rec.sameHolder(t.rec) {
		if err := os.Remove(t.path); err == nil {
			_ = syncDirectory(filepath.Dir(t.path))
		}
	}
}

// reclaimDeadLeaseAt removes an expired or corrupt lease at path, leaving a
// live record (and an absent path) untouched. It is used by open-time and
// pre-operation recovery.
func reclaimDeadLeaseAt(path string) (bool, error) {
	_, live, dead, err := leaseStateAtPath(path)
	if err != nil || live || !dead {
		return false, err
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return false, err
	}
	return true, syncDirectory(filepath.Dir(path))
}

// liveMergeLease reports whether a merge currently holds a live sibling lease
// for the chain named chainDir. A missing parent or chain is no lease.
func liveMergeLease(chainDir string) bool {
	_, live, _, err := leaseStateAtPath(mergeLeasePath(chainDir))
	return err == nil && live
}

// recoverChainCoordination reclaims coordination debris a killed holder can
// leave in and next to dir, before any chain operation inspects the chain:
//
//   - a merge killed at any point of its sibling swap is repaired exactly as
//     sweepMergeDebris already does (old chain moved back when the chain path
//     is missing; staging/trash siblings removed), but only while no live
//     merge lease guards an in-progress merge;
//   - an expired or corrupt merge sibling lease is removed with the debris;
//   - an expired or corrupt lease.dat inside dir is reclaimed, and a lease
//     temp is swept.
//
// A live lease is never touched, so an operation mid-flight is unaffected.
func recoverChainCoordination(dir string) {
	sweepMergeDebrisLeased(dir)

	if removed, err := reclaimDeadLeaseAt(filepath.Join(dir, leaseFileName)); err == nil && removed {
		// Chain contents were not modified; the directory force already ran.
	}
	// A leftover lease temp is pure debris from a killed install/renewal.
	if err := os.Remove(filepath.Join(dir, leaseTmpName)); err != nil &&
		!errors.Is(err, fs.ErrNotExist) {
		return
	}
}

// sweepMergeDebrisLeased is the lease-aware form of sweepMergeDebris: while a
// live merge sibling lease exists every staging/trash sibling belongs to that
// running merge and is left exactly where it is. Once the lease is dead
// (expired, corrupt or absent) the existing repair runs and the dead lease
// record is removed with the debris.
func sweepMergeDebrisLeased(chainDir string) {
	parent := filepath.Dir(chainDir)
	base := filepath.Base(chainDir)
	leasePath := mergeLeasePath(chainDir)

	entries, err := os.ReadDir(parent)
	if err != nil {
		return
	}
	var staging, trash []string
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		name := e.Name()
		if isMergeTempName(name, base, mergeStagePrefix) {
			staging = append(staging, name)
		}
		if isMergeTempName(name, base, mergeTrashPrefix) {
			trash = append(trash, name)
		}
	}

	// A live merge owns whatever staging/trash siblings exist: recover
	// nothing. The chain itself must not be moved or deleted under it.
	if rec, live, _, lerr := leaseStateAtPath(leasePath); lerr == nil && live {
		_ = rec
		return
	}

	if len(staging) == 0 && len(trash) == 0 {
		// No debris: still reap a dead sibling lease if one lingers.
		if _, derr := reclaimDeadLeaseAt(leasePath); derr == nil {
			// best effort
		}
		return
	}

	changed := false
	if _, err := os.Stat(chainDir); errors.Is(err, fs.ErrNotExist) && len(trash) > 0 {
		// Killed between the two commit renames: the whole old chain is parked
		// in the trash sibling. Move it back before clearing anything; the
		// chain name must never disappear with the old chain parked aside.
		if err := os.Rename(filepath.Join(parent, trash[0]), chainDir); err == nil {
			changed = true
			trash = trash[1:]
		}
	}
	for _, name := range staging {
		if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
			changed = true
		}
	}
	for _, name := range trash {
		if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
			changed = true
		}
	}
	if removed, err := reclaimDeadLeaseAt(leasePath); err == nil && removed {
		changed = true
	}
	if changed {
		_ = syncDirectory(parent)
	}
}

// describeLease renders one record for error messages and diagnostics.
func (r leaseRecord) String() string {
	return fmt.Sprintf("kind=%d pid=%d host=%q issued=%d expires=%d",
		r.kind, r.pid, r.host, r.issued, r.expires)
}

// ensure sync is referenced for the unused-import guard on platforms where
// future lease helpers need a mutex; holder identity is otherwise lock-free.
var _ = sync.Mutex{}

