func (s *Store) MergeChain(chainDir string, rings int) error {
	if s.closed.Load() {
		return errStoreClosed
	}
	// Serialize with incremental exports driven by this store so a merge and
	// an export never race to reshape the same chain. This lock is
	// independent of mu: it is held across the merge's disk I/O and never
	// blocks commits or lock-free reads.
	s.backupMu.Lock()
	defer s.backupMu.Unlock()
	if s.closed.Load() {
		return errStoreClosed
	}
	if chainDir == "" || rings < 1 {
		return errBadBackup
	}
	// Take the cross-storage chain lease before touching anything. A live
	// lease held by another backup, incremental export, merge or restore fails
	// the whole merge with fs.ErrInvalid and leaves the chain untouched; a
	// lease whose holder was killed (expired or corrupt) is reclaimed first.
	// The merge lease is a sibling of the chain directory, not a file inside
	// it, so it stays live and identifiable across the directory swap below.
	lease, err := acquireLease(chainDir, leaseKindMerge)
	if err != nil {
		return err
	}
	defer lease.release()
	// Repair or clear debris from a merge killed mid-commit before inspecting
	// the chain, exactly as the next backup or open of the directory would.
	// With the lease in hand no other holder can be recovering concurrently.
	recoverChainCoordination(chainDir)
	info, err := os.Stat(chainDir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return errBadBackup
		}
		return err
	}
	if !info.IsDir() {
		return errBadBackup
	}
	// Clear staging debris from an export (full or incremental) killed
	// mid-run; a manifest temp is pure debris as well.
	for _, stage := range []string{incrStageDir, backupStageDir} {
		if err := os.RemoveAll(filepath.Join(chainDir, stage)); err != nil {
			return err
		}
	}
	if err := os.Remove(filepath.Join(chainDir, backupManifestTmp)); err != nil &&
		!errors.Is(err, os.ErrNotExist) {
		return err
	}

	art, err := validateBackupChain(chainDir)
	if err != nil {
		return err
	}
	if uint64(rings) > uint64(art.ringCount) {
		return errBadBackup
	}

