func (s *Store) Backup(outDir string) error {
	if s.closed.Load() {
		return errStoreClosed
	}
	if outDir == "" {
		return errBadBackup
	}

	info, err := os.Stat(outDir)
	if err != nil {
		if !errors.Is(err, os.ErrNotExist) {
			return err
		}
		if err := os.MkdirAll(outDir, 0o700); err != nil {
			return err
		}
	} else if !info.IsDir() {
		return errBadBackup
	}

	// Take the cross-storage chain lease before clearing debris or writing
	// anything: a full export is exclusive with concurrent incremental
	// exports, merges and restores against the same directory. A live lease
	// fails the whole export with fs.ErrInvalid; an expired or corrupt lease
	// (a holder killed mid-run) is reclaimed first.
	lease, lerr := acquireLease(outDir, leaseKindFull)
	if lerr != nil {
		return lerr
	}
	defer lease.release()
	// Debris from a merge killed mid-commit next to this directory, and any
	// dead lease record, are repaired or swept before the artifact inspection.
	recoverChainCoordination(outDir)
	if err := prepareBackupDir(outDir); err != nil {
		return err
	}

	// Anchor at one fixed watermark. This is the only moment the export takes
	// the write lock; everything after it streams from an immutable view.
	s.mu.Lock()
	if s.closed.Load() {
		s.mu.Unlock()
		return errStoreClosed
	}
	anchor := backupAnchor{
		view:      s.current.Load(),
		watermark: s.nextSeq,
		snaps:     s.snapshots.Load(),
	}
	s.mu.Unlock()

	return writeBackup(outDir, anchor)
}

