// sweepMergeDebrisLeased is the lease-aware form of the old sweep: while a
// live merge sibling lease exists (held by a merge in another process) every
// staging/trash sibling belongs to that running merge and is left exactly
// where it is, and the chain is never moved or deleted under it. Once the
// lease is dead (expired, corrupt or absent) the repair runs and the dead
// lease record and its temps are removed with the debris.
func sweepMergeDebrisLeased(chainDir string) {
	if _, live, _, err := leaseStateAtPath(mergeLeasePath(chainDir)); err == nil && live {
		return
	}
	sweepMergeDebrisCore(chainDir, false)
}

// sweepMergeDebrisOwned repairs merge siblings on behalf of a holder that has
// already acquired the merge lease itself: that lease is live and must be
// preserved, while any staging/trash siblings are leftovers of a prior killed
// merge and are repaired or swept.
func sweepMergeDebrisOwned(chainDir string) {
	sweepMergeDebrisCore(chainDir, true)
}

// sweepMergeDebrisCore performs the actual sibling repair. When keepLease is
// false (recovery outside any lease) a dead sibling lease is removed together
// with the debris; when true (the caller owns that lease) it is never
// removed, only its stray temp files are swept.
func sweepMergeDebrisCore(chainDir string, keepLease bool) {
	parent := filepath.Dir(chainDir)
	base := filepath.Base(chainDir)
	leasePath := mergeLeasePath(chainDir)

	entries, err := os.ReadDir(parent)
	if err != nil {
		return
	}
	var staging, trash []string
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		name := e.Name()
		if isMergeTempName(name, base, mergeStagePrefix) {
			staging = append(staging, name)
		}
		if isMergeTempName(name, base, mergeTrashPrefix) {
			trash = append(trash, name)
		}
	}

	changed := false
	if _, serr := os.Stat(chainDir); errors.Is(serr, fs.ErrNotExist) && len(trash) > 0 {
		// Killed between the two commit renames: the whole old chain is parked
		// in the trash sibling. Move it back before clearing anything; the
		// chain name must never disappear while the old chain is parked aside.
		if err := os.Rename(filepath.Join(parent, trash[0]), chainDir); err == nil {
			changed = true
			trash = trash[1:]
		}
	}
	for _, name := range staging {
		if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
			changed = true
		}
	}
	for _, name := range trash {
		if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
			changed = true
		}
	}
	if !keepLease {
		if err := os.Remove(leasePath); err == nil {
			changed = true
		}
	}
	sweepLeaseTmps(parent, filepath.Base(leasePath))
	if changed {
		_ = syncDirectory(parent)
	}
}

