			path:    claimPath,
			tmpPath: claimPath + ".tmp-renew-" + hex.EncodeToString(rec.nonce[:]),
			rec:     rec,
			origin:  origin,
			stop:    make(chan struct{}),
			done:    make(chan struct{}),

