11		"path/filepath"
12		"time"
13	)
14	
15	// Cross-storage coordination of one shared backup chain.
16	//
17	// The chain directory has no owner on its own: several Store objects, even in
18	// different processes, can be asked to run a full export, an incremental ring
19	// append, a chain merge or a restore against the same chain directory at the
20	// same time. The lease is the one self-describing holder record that makes
21	// chain advancement exclusive:
22	//
23	//	lease.dat            held inside the chain directory by a full export, an
24	//	                     incremental append or a restore
25	//	<chain>.merge-lease  held next to the chain directory by a merge, so it
26	//	                     stays live across the merge's directory swap
27	//
28	// A lease names its holder (operation kind, process id, host, issue time and a
29	// random nonce) and carries an absolute expiry time. The holder that created
30	// it is the only request allowed to advance the chain; every other request
31	// finds the live lease, fails the whole operation without touching the chain,
32	// and reports an error wrapping fs.ErrInvalid. Only the two standard error
33	// classes ever escape: fs.ErrInvalid for contention and every malformed chain
34	// case, fs.ErrClosed for an operation on a closed store.
35	//
36	// Leases are crash-safe: the file is built under a unique temporary name,
37	// forced and hard-linked into place (link(2) never overwrites), so a lease is
38	// either wholly present or absent. A holder killed mid-operation stops
39	// renewing its lease; once the expiry passes the next backup, incremental
40	// export, merge, restore or open of the directory treats the lease as dead,
41	// removes it, and takes over — the chain underneath is either the old chain
42	// or one complete new chain, so recovery never needs a manual step and cannot
43	// deadlock. A well-formed lease that has not reached its expiry is never
44	// taken over: the contender fails with fs.ErrInvalid and changes nothing. An
45	// unparseable lease cannot be a live holder (a live holder only ever installs
46	// a complete file), so it is treated as dead debris and reclaimed rather than
47	// wedging the chain.
48	//
49	// A live holder renews its lease periodically, atomically rewriting the same
50	// record with a moved-out expiry, so a long streamed export or merge keeps the
51	// lease while its process is alive regardless of chain length.
52	//
53	// Lease file layout (all integers little-endian):
54	//
55	//	magic    uint32   leaseMagic
56	//	version  uint32   leaseVersion
57	//	kind     uint8    leaseKind{Full,Incremental,Merge,Restore}
58	//	hostLen  uint16   bytes of the host name
59	//	pid      uint64   holder process id
60	//	issued   uint64   holder issue time, Unix nanoseconds
61	//	expires  uint64   lease expiry time, Unix nanoseconds
62	//	nonce    [8]byte  random holder identity
63	//	host     [hostLen]byte
64	//	crc      uint32   IEEE CRC-32 of every preceding byte
65	const (
66		leaseFileName = "lease.dat"
67		leaseTmpName  = "lease.dat.tmp"
68		// mergeLeaseSuffix names a merge's lease as a sibling of the chain
69		// directory: filepath.Join(parent, base+mergeLeaseSuffix).
70		mergeLeaseSuffix = ".merge-lease"
71	
72		leaseMagic   uint32 = 0x5341454c // bytes "LEAS"
73		leaseVersion uint32 = 1
74	
75		leaseKindFull        byte = 1
76		leaseKindIncremental byte = 2
77		leaseKindMerge       byte = 3
78		leaseKindRestore     byte = 4
79	
80		leaseFixedSize = 4 + 4 + 1 + 2 + 8 + 8 + 8 + 8 // magic, version, kind, hostLen, pid, issued, expires, nonce
81	)
82	
83	// leaseTTL is how long one lease record stays valid without renewal. It is
84	// short enough that a killed holder is reclaimed promptly, while a live
85	// holder rewrites the record well inside it. Tests override it.
86	var leaseTTL = 10 * time.Second
87	
88	// leaseNow is the clock the lease protocol reads; tests override it.
89	var leaseNow = time.Now
90	
91	// errLeaseBusy is reported when a live, unexpired lease held by another
92	// holder blocks chain advancement. It wraps fs.ErrInvalid like every other
93	// whole-operation rejection; no third error class is introduced.
94	var errLeaseBusy = errors.Join(
95		errors.New("snapshot: backup chain is leased by another holder"),
96		fs.ErrInvalid,
97	)
98	
99	// leaseRecord is the parsed identity and validity window of one lease file.
100	type leaseRecord struct {
101		kind    byte
102		pid     uint64
103		issued  int64
104		expires int64
105		nonce   [8]byte
106		host    string
107	}
108	
109	// sameHolder reports whether two records identify the same lease holder. The
110	// renewal-rewritten expiry is deliberately not part of the identity.
111	func (r leaseRecord) sameHolder(o leaseRecord) bool {
112		return r.kind == o.kind && r.pid == o.pid && r.issued == o.issued &&
113			r.nonce == o.nonce && r.host == o.host
114	}
115	
116	// leaseToken is one acquired lease. Its holder must call release exactly
117	// once; the background renewer stops first.
118	type leaseToken struct {
119		path    string       // lease file this token owns
120		tmpPath string       // unique temp name installs and renewals rewrite through
121		rec     leaseRecord
122		origin  os.FileInfo // identity of the file this token claimed (inode)
123	
124		stop chan struct{}
125		done chan struct{}
126	}
127	
128	// mergeLeasePath is the sibling path a merge lease for chainDir occupies.
129	func mergeLeasePath(chainDir string) string {
130		return filepath.Join(filepath.Dir(chainDir), filepath.Base(chainDir)+mergeLeaseSuffix)
131	}
132	
133	// encodeLease serializes rec into a self-describing record ending in its CRC.
134	func encodeLease(rec leaseRecord) []byte {
135		host := []byte(rec.host)
136		buf := make([]byte, leaseFixedSize+len(host)+crcSize)
137		binary.LittleEndian.PutUint32(buf[0:4], leaseMagic)
138		binary.LittleEndian.PutUint32(buf[4:8], leaseVersion)
139		buf[8] = rec.kind
140		binary.LittleEndian.PutUint16(buf[9:11], uint16(len(host)))
141		binary.LittleEndian.PutUint64(buf[11:19], rec.pid)
142		binary.LittleEndian.PutUint64(buf[19:27], uint64(rec.issued))
143		binary.LittleEndian.PutUint64(buf[27:35], uint64(rec.expires))
144		copy(buf[35:43], rec.nonce[:])
145		copy(buf[leaseFixedSize:], host)
146		crc := crc32.ChecksumIEEE(buf[:leaseFixedSize+len(host)])
147		binary.LittleEndian.PutUint32(buf[leaseFixedSize+len(host):], crc)
148		return buf
149	}
150	
151	// parseLease decodes and fully verifies one lease file's bytes. A truncated,
152	// corrupt or foreign record returns ok=false: such bytes can never be a live
153	// holder's record (holders only install a complete linked file), so the
154	// caller treats the file as dead debris.
155	func parseLease(data []byte) (leaseRecord, bool) {
156		var zero leaseRecord
157		if len(data) < leaseFixedSize+crcSize {
158			return zero, false
159		}
160		hostLen := int(binary.LittleEndian.Uint16(data[9:11]))
161		if len(data) != leaseFixedSize+hostLen+crcSize {
162			return zero, false
163		}
164		if binary.LittleEndian.Uint32(data[0:4]) != leaseMagic ||
165			binary.LittleEndian.Uint32(data[4:8]) != leaseVersion {
166			return zero, false
167		}
168		if binary.LittleEndian.Uint32(data[len(data)-crcSize:]) !=
169			crc32.ChecksumIEEE(data[:leaseFixedSize+hostLen]) {
170			return zero, false
171		}
172		kind := data[8]
173		if kind != leaseKindFull && kind != leaseKindIncremental &&
174			kind != leaseKindMerge && kind != leaseKindRestore {
175			return zero, false
176		}
177		rec := leaseRecord{
178			kind:    kind,
179			pid:     binary.LittleEndian.Uint64(data[11:19]),
180			issued:  int64(binary.LittleEndian.Uint64(data[19:27])),
181			expires: int64(binary.LittleEndian.Uint64(data[27:35])),
182			host:    string(data[leaseFixedSize : leaseFixedSize+hostLen]),
183		}
184		copy(rec.nonce[:], data[35:43])
185		return rec, true
186	}
187	
188	// leaseStateAtPath reads and classifies one lease path.
189	//
190	//	live=true:  a well-formed, unexpired lease — a contender must fail
191	//	dead=true:  a well-formed but expired lease, or an unparseable/non-file
192	//	            entry — the caller may reclaim the path
193	//	both false: no lease is present
194	//
195	// A genuine read error other than "not exists" passes through.
196	func leaseStateAtPath(path string) (rec leaseRecord, live, dead bool, err error) {
197		data, rerr := os.ReadFile(path)
198		if rerr != nil {
199			if errors.Is(rerr, fs.ErrNotExist) {
200				return rec, false, false, nil
201			}
202			// A directory or other non-regular entry occupying a lease name is
203			// foreign debris, never a live holder's record.
204			if info, serr := os.Stat(path); serr == nil && !info.Mode().IsRegular() {
205				return rec, false, true, nil
206			}
207			return rec, false, false, rerr
208		}
209		parsed, ok := parseLease(data)
210		if !ok {
211			return rec, false, true, nil // corrupt debris, never a live holder
212		}
213		if leaseNow().UnixNano() >= parsed.expires {
214			return parsed, false, true, nil
215		}
216		return parsed, true, false, nil
217	}
218	
219	// writeLeaseFile durably writes data to a fresh temp name, forces it, and
220	// returns the temp path (the caller links it into its final name).
221	func writeLeaseFile(tmpPath string, data []byte) error {
222		tmp, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_TRUNC|os.O_EXCL, 0o600)
223		if err != nil {
224			return err
225		}
226		fail := func(err error) error {
227			tmp.Close()
228			os.Remove(tmpPath)
229			return err
230		}
231		if _, err := tmp.Write(data); err != nil {
232			return fail(err)
233		}
234		if err := tmp.Sync(); err != nil {
235			return fail(err)
236		}
237		if err := tmp.Close(); err != nil {
238			os.Remove(tmpPath)
239			return err
240		}
241		return nil
242	}
243	
244	// rewriteLease atomically replaces an owned lease file with data via a rename
245	// over its own temp name (the holder already owns the final name exclusively).
246	func rewriteLease(path, tmpPath string, data []byte) error {
247		tmp, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
248		if err != nil {
249			return err
250		}
251		fail := func(err error) error {
252			tmp.Close()
253			os.Remove(tmpPath)
254			return err
255		}
256		if _, err := tmp.Write(data); err != nil {
257			return fail(err)
258		}
259		if err := tmp.Sync(); err != nil {
260			return fail(err)
261		}
262		if err := tmp.Close(); err != nil {
263			os.Remove(tmpPath)
264			return err
265		}
266		if err := os.Rename(tmpPath, path); err != nil {
267			os.Remove(tmpPath)
268			return err
269		}
270		return syncDirectory(filepath.Dir(path))
271	}
272	
273	// newHolderRecord builds a fresh identity for kind, valid from now until the
274	// current lease TTL elapses.
275	func newHolderRecord(kind byte) (leaseRecord, error) {
276		rec := leaseRecord{
277			kind:    kind,
278			pid:     uint64(os.Getpid()),
279			issued:  leaseNow().UnixNano(),
280			expires: leaseNow().Add(leaseTTL).UnixNano(),
281			host:    hostname(),
282		}
283		if _, err := rand.Read(rec.nonce[:]); err != nil {
284			return rec, err
285		}
286		return rec, nil
287	}
288	
289	// hostname returns a short best-effort holder host label; it is descriptive
290	// only and never participates in exclusion.
291	func hostname() string {
292		name, err := os.Hostname()
293		if err != nil || name == "" {
294			return "unknown-host"
295		}
296		return name
297	}
298	
299	// acquireLease takes exclusive advancement rights over the backup chain in
300	// dir. kind selects which lease path is owned: a merge holds its lease as a
301	// stable sibling of dir (the directory itself is renamed during the merge
302	// commit); every other kind holds lease.dat inside dir. Either way the call
303	// fails with errLeaseBusy when a live lease of any kind guards the chain,
304	// reclaims an expired or corrupt lease first, and otherwise installs a fresh
305	// lease atomically with a never-overwriting hard link.
306	func acquireLease(dir string, kind byte) (*leaseToken, error) {
307		inside := filepath.Join(dir, leaseFileName)
308		sibling := mergeLeasePath(dir)
309		claimPath := inside
310		if kind == leaseKindMerge {
311			claimPath = sibling
312		}
313	
314		// A bounded number of reclaim/claim rounds absorbs races with other
315		// processes also discovering a dead lease; contention on a live lease
316		// fails on the first inspection.
317		for attempt := 0; attempt < 100; attempt++ {
318			// Both lease positions guard the same chain.
319			for _, p := range []string{inside, sibling} {
320				_, live, dead, err := leaseStateAtPath(p)
321				if err != nil {
322					return nil, err
323				}
324				if live {
325					return nil, errLeaseBusy
326				}
327				if dead {
328					if err := removeLeaseDebris(p); err != nil {
329						return nil, err
330					}
331				}
332			}
333	
334			rec, err := newHolderRecord(kind)
335			if err != nil {
336				return nil, err
337			}
338			data := encodeLease(rec)
339			tmpPath := claimPath + ".tmp-" + hex.EncodeToString(rec.nonce[:])
340			if err := writeLeaseFile(tmpPath, data); err != nil {
341				if errors.Is(err, fs.ErrExist) {
342					continue // astronomically unlikely nonce clash; retry
343				}
344				return nil, err
345			}
346			// link(2) fails rather than overwrite: exactly one contender claims.
347			if lerr := os.Link(tmpPath, claimPath); lerr != nil {
348				os.Remove(tmpPath)
349				if errors.Is(lerr, fs.ErrExist) {
350					continue // another contender claimed first; re-inspect
351				}
352				return nil, lerr
353			}
354			os.Remove(tmpPath)
355			if err := syncDirectory(filepath.Dir(claimPath)); err != nil {
356				return nil, err
357			}
358			origin, err := os.Stat(claimPath)
359			if err != nil {
360				os.Remove(claimPath)
361				return nil, err
362			}
363			tok := &leaseToken{
364				path:    claimPath,
365				tmpPath: claimPath + ".tmp-renew-" + hex.EncodeToString(rec.nonce[:]),
366				rec:     rec,
367				origin:  origin,
368				stop:    make(chan struct{}),
369				done:    make(chan struct{}),
370			}
371			go tok.renew(data)
372			return tok, nil
373		}
374		return nil, errLeaseBusy
375	}
376	
377	// stillOurs reports that the lease path still names this token's own file and
378	// its record still identifies this holder. It is the guard every renewal and
379	// release uses: a holder that stalled past its TTL and was reclaimed must
380	// never touch the lease a contender has since installed.
381	func (t *leaseToken) stillOurs() bool {
382		cur, live, _, err := leaseStateAtPath(t.path)
383		if err != nil || !live || !cur.sameHolder(t.rec) {
384			return false
385		}
386		info, err := os.Stat(t.path)
387		if err != nil {
388			return false
389		}
390		return os.SameFile(info, t.origin)
391	}
392	
393	// renew keeps the lease ahead of its expiry while the holder operation runs.
394	// Every rewrite is the same all-or-nothing install, so contenders only ever
395	// read a complete record. A rewrite happens only while the path is still this
396	// holder's own lease; once it is not (the lease aged out and was taken over),
397	// the renewer stops and never overwrites the successor. A failed renewal
398	// simply lets this lease age; the operation itself is unaffected.
399	func (t *leaseToken) renew(_ []byte) {
400		defer close(t.done)
401		gap := leaseTTL / 3
402		if gap <= 0 {
403			gap = leaseTTL
404		}
405		ticker := time.NewTicker(gap)
406		defer ticker.Stop()
407		for {
408			select {
409			case <-t.stop:
410				return
411			case <-ticker.C:
412				if !t.stillOurs() {
413					return
414				}
415				t.rec.expires = leaseNow().Add(leaseTTL).UnixNano()
416				if err := rewriteLease(t.path, t.tmpPath, encodeLease(t.rec)); err != nil {
417					return
418				}
419			}
420		}
421	}
422	
423	// release surrenders the lease. It removes only a record that still identifies
424	// this exact holder: if the lease aged out, was reclaimed and was taken over
425	// by another holder, that newer lease is left in place. Removing the record
426	// never touches the chain itself.
427	func (t *leaseToken) release() {
428		close(t.stop)
429		<-t.done
430		if t.stillOurs() {
431			if err := os.Remove(t.path); err == nil {
432				_ = syncDirectory(filepath.Dir(t.path))
433			}
434		}
435		os.Remove(t.tmpPath)
436	}
437	
438	// removeLeaseDebris deletes one dead lease position and the unique temp files
439	// a killed install or renewal could leave next to it, forcing the directory.
440	func removeLeaseDebris(leasePath string) error {
441		if err := os.Remove(leasePath); err != nil && !errors.Is(err, fs.ErrNotExist) {
442			return err
443		}
444		sweepLeaseTmps(filepath.Dir(leasePath), filepath.Base(leasePath))
445		return syncDirectory(filepath.Dir(leasePath))
446	}
447	
448	// sweepLeaseTmps removes regular files that are install/renewal temps of the
449	// lease at dir/<leaseName>: they share the "<leaseName>.tmp" prefix. Best
450	// effort.
451	func sweepLeaseTmps(dir, leaseName string) {
452		prefix := leaseName + ".tmp"
453		entries, err := os.ReadDir(dir)
454		if err != nil {
455			return
456		}
457		for _, e := range entries {
458			if e.IsDir() {
459				continue
460			}
461			name := e.Name()
462			if len(name) > len(prefix) && name[:len(prefix)] == prefix {
463				_ = os.Remove(filepath.Join(dir, name))
464			}
465		}
466	}
467	
468	// isLeaseCoordinationName reports whether name is the live lease file or one
469	// of its temporary names. Chain validation and directory preparation treat
470	// these names as coordination metadata, never as foreign artifact files.
471	func isLeaseCoordinationName(name string) bool {
472		return name == leaseFileName ||
473			(len(name) > len(leaseTmpName) && name[:len(leaseTmpName)] == leaseTmpName)
474	}
475	
476	// recoverChainCoordination reclaims coordination debris a killed holder can
477	// leave in and next to dir, before any chain operation inspects the chain:
478	//
479	//   - a merge killed at any point of its sibling swap is repaired (old chain
480	//     moved back when the chain path is missing; staging/trash siblings
481	//     removed), but only while no live merge lease guards an in-progress
482	//     merge;
483	//   - an expired, corrupt or absent lease position's debris is reclaimed,
484	//     including its install/renewal temp files;
485	//   - a live lease and its temp files are never touched.
486	func recoverChainCoordination(dir string) {
487		sweepMergeDebrisLeased(dir)
488		recoverInsideLease(dir)
489	}
490	
491	// recoverChainCoordinationOwned runs after the caller has itself acquired the
492	// chain lease. It repairs merge staging/trash siblings unconditionally (the
493	// lease that guarded the killed merge is dead or is the caller's own). A merge
494	// holder keeps its own live sibling lease; every other kind of holder holds
495	// the inside lease and reaps a dead sibling merge lease. The holder's own
496	// lease is never touched.
497	func recoverChainCoordinationOwned(dir string, kind byte) {
498		sweepMergeDebrisCore(dir, kind == leaseKindMerge)
499	}
500	
501	// recoverInsideLease reclaims a dead lease.dat and its temp files inside dir;
502	// a live lease is left exactly as it stands. Best effort.
503	func recoverInsideLease(dir string) {
504		path := filepath.Join(dir, leaseFileName)
505		_, live, dead, err := leaseStateAtPath(path)
506		if err != nil {
507			return
508		}
509		if live {
510			return
511		}
512		if dead {
513			_ = os.Remove(path)
514		}
515		// No live holder owns these names; a fresh acquire uses its own unique
516		// temp name, so every leftover temp is debris.
517		entries, err := os.ReadDir(dir)
518		if err != nil {
519			return
520		}
521		for _, e := range entries {
522			if !e.IsDir() && isLeaseCoordinationName(e.Name()) && e.Name() != leaseFileName {
523				_ = os.Remove(filepath.Join(dir, e.Name()))
524			}
525		}
526		_ = syncDirectory(dir)
527	}
528	
529	// sweepMergeDebrisLeased is the lease-aware form of the old sweep: while a
530	// live merge sibling lease exists (held by a merge in another process) every
531	// staging/trash sibling belongs to that running merge and is left exactly
532	// where it is, and the chain is never moved or deleted under it. Once the
533	// lease is dead (expired, corrupt or absent) the repair runs and the dead
534	// lease record and its temps are removed with the debris.
535	func sweepMergeDebrisLeased(chainDir string) {
536		if _, live, _, err := leaseStateAtPath(mergeLeasePath(chainDir)); err == nil && live {
537			return
538		}
539		sweepMergeDebrisCore(chainDir, false)
540	}
541	
542	// sweepMergeDebrisCore performs the actual sibling repair. When keepLease is
543	// false (recovery outside any lease) a dead sibling lease is removed together
544	// with the debris; when true (the caller owns that lease) it is never
545	// removed, only its stray temp files are swept.
546	func sweepMergeDebrisCore(chainDir string, keepLease bool) {
547		parent := filepath.Dir(chainDir)
548		base := filepath.Base(chainDir)
549		leasePath := mergeLeasePath(chainDir)
550	
551		entries, err := os.ReadDir(parent)
552		if err != nil {
553			return
554		}
555		var staging, trash []string
556		for _, e := range entries {
557			if !e.IsDir() {
558				continue
559			}
560			name := e.Name()
561			if isMergeTempName(name, base, mergeStagePrefix) {
562				staging = append(staging, name)
563			}
564			if isMergeTempName(name, base, mergeTrashPrefix) {
565				trash = append(trash, name)
566			}
567		}
568	
569		changed := false
570		if _, serr := os.Stat(chainDir); errors.Is(serr, fs.ErrNotExist) && len(trash) > 0 {
571			// Killed between the two commit renames: the whole old chain is parked
572			// in the trash sibling. Move it back before clearing anything; the
573			// chain name must never disappear while the old chain is parked aside.
574			if err := os.Rename(filepath.Join(parent, trash[0]), chainDir); err == nil {
575				changed = true
576				trash = trash[1:]
577			}
578		}
579		for _, name := range staging {
580			if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
581				changed = true
582			}
583		}
584		for _, name := range trash {
585			if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
586				changed = true
587			}
588		}
589		if !keepLease {
590			if err := os.Remove(leasePath); err == nil {
591				changed = true
592			}
593		}
594		sweepLeaseTmps(parent, filepath.Base(leasePath))
595		if changed {
596			_ = syncDirectory(parent)
597		}
598	}
