package snapshot

import (
	"crypto/rand"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"hash/crc32"
	"io/fs"
	"os"
	"path/filepath"
	"time"
)

// Cross-storage coordination of one shared backup chain.
//
// The chain directory has no owner on its own: several Store objects, even in
// different processes, can be asked to run a full export, an incremental ring
// append, a chain merge or a restore against the same chain directory at the
// same time. The lease is the one self-describing holder record that makes
// chain advancement exclusive:
//
//	lease.dat            held inside the chain directory by a full export, an
//	                     incremental append or a restore
//	<chain>.merge-lease  held next to the chain directory by a merge, so it
//	                     stays live across the merge's directory swap
//
// A lease names its holder (operation kind, process id, host, issue time and a
// random nonce) and carries an absolute expiry time. The holder that created
// it is the only request allowed to advance the chain; every other request
// finds the live lease, fails the whole operation without touching the chain,
// and reports an error wrapping fs.ErrInvalid. Only the two standard error
// classes ever escape: fs.ErrInvalid for contention and every malformed chain
// case, fs.ErrClosed for an operation on a closed store.
//
// Leases are crash-safe: the file is built under a unique temporary name,
// forced and hard-linked into place (link(2) never overwrites), so a lease is
// either wholly present or absent. A holder killed mid-operation stops
// renewing its lease; once the expiry passes the next backup, incremental
// export, merge, restore or open of the directory treats the lease as dead,
// removes it, and takes over — the chain underneath is either the old chain
// or one complete new chain, so recovery never needs a manual step and cannot
// deadlock. A well-formed lease that has not reached its expiry is never
// taken over: the contender fails with fs.ErrInvalid and changes nothing. An
// unparseable lease cannot be a live holder (a live holder only ever installs
// a complete file), so it is treated as dead debris and reclaimed rather than
// wedging the chain.
//
// A live holder renews its lease periodically, atomically rewriting the same
// record with a moved-out expiry, so a long streamed export or merge keeps the
// lease while its process is alive regardless of chain length.
//
// Lease file layout (all integers little-endian):
//
//	magic    uint32   leaseMagic
//	version  uint32   leaseVersion
//	kind     uint8    leaseKind{Full,Incremental,Merge,Restore}
//	hostLen  uint16   bytes of the host name
//	pid      uint64   holder process id
//	issued   uint64   holder issue time, Unix nanoseconds
//	expires  uint64   lease expiry time, Unix nanoseconds
//	nonce    [8]byte  random holder identity
//	host     [hostLen]byte
//	crc      uint32   IEEE CRC-32 of every preceding byte
const (
	leaseFileName = "lease.dat"
	leaseTmpName  = "lease.dat.tmp"
	// mergeLeaseSuffix names a merge's lease as a sibling of the chain
	// directory: filepath.Join(parent, base+mergeLeaseSuffix).
	mergeLeaseSuffix = ".merge-lease"

	leaseMagic   uint32 = 0x5341454c // bytes "LEAS"
	leaseVersion uint32 = 1

	leaseKindFull        byte = 1
	leaseKindIncremental byte = 2
	leaseKindMerge       byte = 3
	leaseKindRestore     byte = 4

	leaseFixedSize = 4 + 4 + 1 + 2 + 8 + 8 + 8 + 8 // magic, version, kind, hostLen, pid, issued, expires, nonce
)

// leaseTTL is how long one lease record stays valid without renewal. It is
// short enough that a killed holder is reclaimed promptly, while a live
// holder rewrites the record well inside it. Tests override it.
var leaseTTL = 10 * time.Second

// leaseNow is the clock the lease protocol reads; tests override it.
var leaseNow = time.Now

// errLeaseBusy is reported when a live, unexpired lease held by another
// holder blocks chain advancement. It wraps fs.ErrInvalid like every other
// whole-operation rejection; no third error class is introduced.
var errLeaseBusy = errors.Join(
	errors.New("snapshot: backup chain is leased by another holder"),
	fs.ErrInvalid,
)

// leaseRecord is the parsed identity and validity window of one lease file.
type leaseRecord struct {
	kind    byte
	pid     uint64
	issued  int64
	expires int64
	nonce   [8]byte
	host    string
}

// sameHolder reports whether two records identify the same lease holder. The
// renewal-rewritten expiry is deliberately not part of the identity.
func (r leaseRecord) sameHolder(o leaseRecord) bool {
	return r.kind == o.kind && r.pid == o.pid && r.issued == o.issued &&
		r.nonce == o.nonce && r.host == o.host
}

// leaseToken is one acquired lease. Its holder must call release exactly
// once; the background renewer stops first.
type leaseToken struct {
	path    string       // lease file this token owns
	tmpPath string       // unique temp name installs and renewals rewrite through
	rec     leaseRecord
	origin  os.FileInfo // identity of the file this token claimed (inode)

	stop chan struct{}
	done chan struct{}
}

// mergeLeasePath is the sibling path a merge lease for chainDir occupies.
func mergeLeasePath(chainDir string) string {
	return filepath.Join(filepath.Dir(chainDir), filepath.Base(chainDir)+mergeLeaseSuffix)
}

// encodeLease serializes rec into a self-describing record ending in its CRC.
func encodeLease(rec leaseRecord) []byte {
	host := []byte(rec.host)
	buf := make([]byte, leaseFixedSize+len(host)+crcSize)
	binary.LittleEndian.PutUint32(buf[0:4], leaseMagic)
	binary.LittleEndian.PutUint32(buf[4:8], leaseVersion)
	buf[8] = rec.kind
	binary.LittleEndian.PutUint16(buf[9:11], uint16(len(host)))
	binary.LittleEndian.PutUint64(buf[11:19], rec.pid)
	binary.LittleEndian.PutUint64(buf[19:27], uint64(rec.issued))
	binary.LittleEndian.PutUint64(buf[27:35], uint64(rec.expires))
	copy(buf[35:43], rec.nonce[:])
	copy(buf[leaseFixedSize:], host)
	crc := crc32.ChecksumIEEE(buf[:leaseFixedSize+len(host)])
	binary.LittleEndian.PutUint32(buf[leaseFixedSize+len(host):], crc)
	return buf
}

// parseLease decodes and fully verifies one lease file's bytes. A truncated,
// corrupt or foreign record returns ok=false: such bytes can never be a live
// holder's record (holders only install a complete linked file), so the
// caller treats the file as dead debris.
func parseLease(data []byte) (leaseRecord, bool) {
	var zero leaseRecord
	if len(data) < leaseFixedSize+crcSize {
		return zero, false
	}
	hostLen := int(binary.LittleEndian.Uint16(data[9:11]))
	if len(data) != leaseFixedSize+hostLen+crcSize {
		return zero, false
	}
	if binary.LittleEndian.Uint32(data[0:4]) != leaseMagic ||
		binary.LittleEndian.Uint32(data[4:8]) != leaseVersion {
		return zero, false
	}
	if binary.LittleEndian.Uint32(data[len(data)-crcSize:]) !=
		crc32.ChecksumIEEE(data[:leaseFixedSize+hostLen]) {
		return zero, false
	}
	kind := data[8]
	if kind != leaseKindFull && kind != leaseKindIncremental &&
		kind != leaseKindMerge && kind != leaseKindRestore {
		return zero, false
	}
	rec := leaseRecord{
		kind:    kind,
		pid:     binary.LittleEndian.Uint64(data[11:19]),
		issued:  int64(binary.LittleEndian.Uint64(data[19:27])),
		expires: int64(binary.LittleEndian.Uint64(data[27:35])),
		host:    string(data[leaseFixedSize : leaseFixedSize+hostLen]),
	}
	copy(rec.nonce[:], data[35:43])
	return rec, true
}

// leaseStateAtPath reads and classifies one lease path.
//
//	live=true:  a well-formed, unexpired lease — a contender must fail
//	dead=true:  a well-formed but expired lease, or an unparseable/non-file
//	            entry — the caller may reclaim the path
//	both false: no lease is present
//
// A genuine read error other than "not exists" passes through.
func leaseStateAtPath(path string) (rec leaseRecord, live, dead bool, err error) {
	data, rerr := os.ReadFile(path)
	if rerr != nil {
		if errors.Is(rerr, fs.ErrNotExist) {
			return rec, false, false, nil
		}
		// A directory or other non-regular entry occupying a lease name is
		// foreign debris, never a live holder's record.
		if info, serr := os.Stat(path); serr == nil && !info.Mode().IsRegular() {
			return rec, false, true, nil
		}
		return rec, false, false, rerr
	}
	parsed, ok := parseLease(data)
	if !ok {
		return rec, false, true, nil // corrupt debris, never a live holder
	}
	if leaseNow().UnixNano() >= parsed.expires {
		return parsed, false, true, nil
	}
	return parsed, true, false, nil
}

// writeLeaseFile durably writes data to a fresh temp name, forces it, and
// returns the temp path (the caller links it into its final name).
func writeLeaseFile(tmpPath string, data []byte) error {
	tmp, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_TRUNC|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	fail := func(err error) error {
		tmp.Close()
		os.Remove(tmpPath)
		return err
	}
	if _, err := tmp.Write(data); err != nil {
		return fail(err)
	}
	if err := tmp.Sync(); err != nil {
		return fail(err)
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpPath)
		return err
	}
	return nil
}

// rewriteLease atomically replaces an owned lease file with data via a rename
// over its own temp name (the holder already owns the final name exclusively).
func rewriteLease(path, tmpPath string, data []byte) error {
	tmp, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
	if err != nil {
		return err
	}
	fail := func(err error) error {
		tmp.Close()
		os.Remove(tmpPath)
		return err
	}
	if _, err := tmp.Write(data); err != nil {
		return fail(err)
	}
	if err := tmp.Sync(); err != nil {
		return fail(err)
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpPath)
		return err
	}
	if err := os.Rename(tmpPath, path); err != nil {
		os.Remove(tmpPath)
		return err
	}
	return syncDirectory(filepath.Dir(path))
}

// newHolderRecord builds a fresh identity for kind, valid from now until the
// current lease TTL elapses.
func newHolderRecord(kind byte) (leaseRecord, error) {
	rec := leaseRecord{
		kind:    kind,
		pid:     uint64(os.Getpid()),
		issued:  leaseNow().UnixNano(),
		expires: leaseNow().Add(leaseTTL).UnixNano(),
		host:    hostname(),
	}
	if _, err := rand.Read(rec.nonce[:]); err != nil {
		return rec, err
	}
	return rec, nil
}

// hostname returns a short best-effort holder host label; it is descriptive
// only and never participates in exclusion.
func hostname() string {
	name, err := os.Hostname()
	if err != nil || name == "" {
		return "unknown-host"
	}
	return name
}

// acquireLease takes exclusive advancement rights over the backup chain in
// dir. kind selects which lease path is owned: a merge holds its lease as a
// stable sibling of dir (the directory itself is renamed during the merge
// commit); every other kind holds lease.dat inside dir. Either way the call
// fails with errLeaseBusy when a live lease of any kind guards the chain,
// reclaims an expired or corrupt lease first, and otherwise installs a fresh
// lease atomically with a never-overwriting hard link.
func acquireLease(dir string, kind byte) (*leaseToken, error) {
	inside := filepath.Join(dir, leaseFileName)
	sibling := mergeLeasePath(dir)
	claimPath := inside
	if kind == leaseKindMerge {
		claimPath = sibling
	}

	// A bounded number of reclaim/claim rounds absorbs races with other
	// processes also discovering a dead lease; contention on a live lease
	// fails on the first inspection.
	for attempt := 0; attempt < 100; attempt++ {
		// Both lease positions guard the same chain.
		for _, p := range []string{inside, sibling} {
			_, live, dead, err := leaseStateAtPath(p)
			if err != nil {
				return nil, err
			}
			if live {
				return nil, errLeaseBusy
			}
			if dead {
				if err := removeLeaseDebris(p); err != nil {
					return nil, err
				}
			}
		}

		rec, err := newHolderRecord(kind)
		if err != nil {
			return nil, err
		}
		data := encodeLease(rec)
		tmpPath := claimPath + ".tmp-" + hex.EncodeToString(rec.nonce[:])
		if err := writeLeaseFile(tmpPath, data); err != nil {
			if errors.Is(err, fs.ErrExist) {
				continue // astronomically unlikely nonce clash; retry
			}
			return nil, err
		}
		// link(2) fails rather than overwrite: exactly one contender claims.
		if lerr := os.Link(tmpPath, claimPath); lerr != nil {
			os.Remove(tmpPath)
			if errors.Is(lerr, fs.ErrExist) {
				continue // another contender claimed first; re-inspect
			}
			return nil, lerr
		}
		os.Remove(tmpPath)
		if err := syncDirectory(filepath.Dir(claimPath)); err != nil {
			return nil, err
		}
		origin, err := os.Stat(claimPath)
		if err != nil {
			os.Remove(claimPath)
			return nil, err
		}
		tok := &leaseToken{
			path:    claimPath,
			tmpPath: claimPath + ".tmp-renew-" + hex.EncodeToString(rec.nonce[:]),
			rec:     rec,
			origin:  origin,
			stop:    make(chan struct{}),
			done:    make(chan struct{}),
		}
		go tok.renew(data)
		return tok, nil
	}
	return nil, errLeaseBusy
}

// stillOurs reports that the lease path still names this token's own file and
// its record still identifies this holder. It is the guard every renewal and
// release uses: a holder that stalled past its TTL and was reclaimed must
// never touch the lease a contender has since installed.
func (t *leaseToken) stillOurs() bool {
	cur, live, _, err := leaseStateAtPath(t.path)
	if err != nil || !live || !cur.sameHolder(t.rec) {
		return false
	}
	info, err := os.Stat(t.path)
	if err != nil {
		return false
	}
	return os.SameFile(info, t.origin)
}

// renew keeps the lease ahead of its expiry while the holder operation runs.
// Every rewrite is the same all-or-nothing install, so contenders only ever
// read a complete record. A rewrite happens only while the path is still this
// holder's own lease; once it is not (the lease aged out and was taken over),
// the renewer stops and never overwrites the successor. A failed renewal
// simply lets this lease age; the operation itself is unaffected.
func (t *leaseToken) renew(_ []byte) {
	defer close(t.done)
	gap := leaseTTL / 3
	if gap <= 0 {
		gap = leaseTTL
	}
	ticker := time.NewTicker(gap)
	defer ticker.Stop()
	for {
		select {
		case <-t.stop:
			return
		case <-ticker.C:
			if !t.stillOurs() {
				return
			}
			t.rec.expires = leaseNow().Add(leaseTTL).UnixNano()
			if err := rewriteLease(t.path, t.tmpPath, encodeLease(t.rec)); err != nil {
				return
			}
		}
	}
}

// release surrenders the lease. It removes only a record that still identifies
// this exact holder: if the lease aged out, was reclaimed and was taken over
// by another holder, that newer lease is left in place. Removing the record
// never touches the chain itself.
func (t *leaseToken) release() {
	close(t.stop)
	<-t.done
	if t.stillOurs() {
		if err := os.Remove(t.path); err == nil {
			_ = syncDirectory(filepath.Dir(t.path))
		}
	}
	os.Remove(t.tmpPath)
}

// removeLeaseDebris deletes one dead lease position and the unique temp files
// a killed install or renewal could leave next to it, forcing the directory.
func removeLeaseDebris(leasePath string) error {
	if err := os.Remove(leasePath); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	sweepLeaseTmps(filepath.Dir(leasePath), filepath.Base(leasePath))
	return syncDirectory(filepath.Dir(leasePath))
}

// sweepLeaseTmps removes regular files that are install/renewal temps of the
// lease at dir/<leaseName>: they share the "<leaseName>.tmp" prefix. Best
// effort.
func sweepLeaseTmps(dir, leaseName string) {
	prefix := leaseName + ".tmp"
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if len(name) > len(prefix) && name[:len(prefix)] == prefix {
			_ = os.Remove(filepath.Join(dir, name))
		}
	}
}

// isLeaseCoordinationName reports whether name is the live lease file or one
// of its temporary names. Chain validation and directory preparation treat
// these names as coordination metadata, never as foreign artifact files.
func isLeaseCoordinationName(name string) bool {
	return name == leaseFileName ||
		(len(name) > len(leaseTmpName) && name[:len(leaseTmpName)] == leaseTmpName)
}

// recoverChainCoordination reclaims coordination debris a killed holder can
// leave in and next to dir, before any chain operation inspects the chain:
//
//   - a merge killed at any point of its sibling swap is repaired (old chain
//     moved back when the chain path is missing; staging/trash siblings
//     removed), but only while no live merge lease guards an in-progress
//     merge;
//   - an expired, corrupt or absent lease position's debris is reclaimed,
//     including its install/renewal temp files;
//   - a live lease and its temp files are never touched.
func recoverChainCoordination(dir string) {
	sweepMergeDebrisLeased(dir)
	recoverInsideLease(dir)
}

// recoverChainCoordinationOwned runs after the caller has itself acquired the
// chain lease. It repairs merge staging/trash siblings unconditionally (the
// lease that guarded the killed merge is dead or is the caller's own). A merge
// holder keeps its own live sibling lease; every other kind of holder holds
// the inside lease and reaps a dead sibling merge lease. The holder's own
// lease is never touched.
func recoverChainCoordinationOwned(dir string, kind byte) {
	sweepMergeDebrisCore(dir, kind == leaseKindMerge)
}

// recoverInsideLease reclaims a dead lease.dat and its temp files inside dir;
// a live lease is left exactly as it stands. Best effort.
func recoverInsideLease(dir string) {
	path := filepath.Join(dir, leaseFileName)
	_, live, dead, err := leaseStateAtPath(path)
	if err != nil {
		return
	}
	if live {
		return
	}
	if dead {
		_ = os.Remove(path)
	}
	// No live holder owns these names; a fresh acquire uses its own unique
	// temp name, so every leftover temp is debris.
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	for _, e := range entries {
		if !e.IsDir() && isLeaseCoordinationName(e.Name()) && e.Name() != leaseFileName {
			_ = os.Remove(filepath.Join(dir, e.Name()))
		}
	}
	_ = syncDirectory(dir)
}

// sweepMergeDebrisLeased is the lease-aware form of the old sweep: while a
// live merge sibling lease exists (held by a merge in another process) every
// staging/trash sibling belongs to that running merge and is left exactly
// where it is, and the chain is never moved or deleted under it. Once the
// lease is dead (expired, corrupt or absent) the repair runs and the dead
// lease record and its temps are removed with the debris.
func sweepMergeDebrisLeased(chainDir string) {
	if _, live, _, err := leaseStateAtPath(mergeLeasePath(chainDir)); err == nil && live {
		return
	}
	sweepMergeDebrisCore(chainDir, false)
}

// sweepMergeDebrisCore performs the actual sibling repair. When keepLease is
// false (recovery outside any lease) a dead sibling lease is removed together
// with the debris; when true (the caller owns that lease) it is never
// removed, only its stray temp files are swept.
func sweepMergeDebrisCore(chainDir string, keepLease bool) {
	parent := filepath.Dir(chainDir)
	base := filepath.Base(chainDir)
	leasePath := mergeLeasePath(chainDir)

	entries, err := os.ReadDir(parent)
	if err != nil {
		return
	}
	var staging, trash []string
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		name := e.Name()
		if isMergeTempName(name, base, mergeStagePrefix) {
			staging = append(staging, name)
		}
		if isMergeTempName(name, base, mergeTrashPrefix) {
			trash = append(trash, name)
		}
	}

	changed := false
	if _, serr := os.Stat(chainDir); errors.Is(serr, fs.ErrNotExist) && len(trash) > 0 {
		// Killed between the two commit renames: the whole old chain is parked
		// in the trash sibling. Move it back before clearing anything; the
		// chain name must never disappear while the old chain is parked aside.
		if err := os.Rename(filepath.Join(parent, trash[0]), chainDir); err == nil {
			changed = true
			trash = trash[1:]
		}
	}
	for _, name := range staging {
		if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
			changed = true
		}
	}
	for _, name := range trash {
		if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
			changed = true
		}
	}
	if !keepLease {
		if err := os.Remove(leasePath); err == nil {
			changed = true
		}
	}
	sweepLeaseTmps(parent, filepath.Base(leasePath))
	if changed {
		_ = syncDirectory(parent)
	}
}

