// stillOurs reports that the lease path still names this token's own file and
// its record still identifies this holder. It is the guard every renewal and
// release uses: a holder that stalled past its TTL and was reclaimed must
// never touch the lease a contender has since installed.
func (t *leaseToken) stillOurs() bool {
	cur, live, _, err := leaseStateAtPath(t.path)
	if err != nil || !live || !cur.sameHolder(t.rec) {
		return false
	}
	info, err := os.Stat(t.path)
	if err != nil {
		return false
	}
	return os.SameFile(info, t.origin)
}

