// stillOurs reports that the lease path still holds a live record identifying
// this holder. It is the guard every renewal, commit fence and release use: a
// holder that stalled past its TTL and was reclaimed must never touch the
// lease a contender has since installed. The immutable holder identity is the
// fence; a successor always mints a fresh nonce and issue time.
func (t *leaseToken) stillOurs() bool {
	cur, live, _, err := leaseStateAtPath(t.path)
	return err == nil && live && cur.sameHolder(t.rec)
}

