				t.Errorf("bad restore stats")
			}
			rs.Close()
			atomic.AddInt64(&restores, 1)
		case errors.Is(err, errLeaseBusy):
			atomic.AddInt64(&busyOK, 1)
		default:
			t.Errorf("unexpected restore error: %v", err)
		}
		time.Sleep(2 * time.Millisecond)
	}
}()

