// merge to mirror into the staged new chain immediately before its swap. It
// extends the expiry without waiting for the renewal tick.
func (t *leaseToken) recordForSwap() leaseRecord {
	t.rec.expires = leaseNow().Add(leaseTTL).UnixNano()
	return t.rec
}

// renew keeps the lease ahead of its expiry while the holder operation runs.
// Every rewrite is the same all-or-nothing install, so contenders only ever
// read a complete record. The authoritative sibling is always rewritten; the
// in-directory mirror is refreshed too while the chain directory is stable
// (everything but a merge's swap window). A failed renewal simply lets the
// lease age; the operation itself is unaffected.
func (t *leaseToken) renew() {
	defer close(t.done)
	gap := leaseTTL / 3
	if gap <= 0 {
		gap = leaseTTL
	}
	ticker := time.NewTicker(gap)
	defer ticker.Stop()
	for {
		select {
		case <-t.stop:
			return
		case <-ticker.C:
			if !t.stillOurs() {
				return
			}
			t.rec.expires = leaseNow().Add(leaseTTL).UnixNano()
			data := encodeLease(t.rec)
			if err := writeLeaseFile(t.authTmp, data, false); err == nil {
				if err := os.Rename(t.authTmp, t.authPath); err == nil {
					_ = syncDirectory(filepath.Dir(t.authPath))
				} else {
					os.Remove(t.authTmp)
				}
			}
			if t.rec.kind != leaseKindMerge {
				_ = writeInsideMirror(t.dir, t.rec)
			}
		}
	}
}

